 48	package com.pousadamarealta.db;
 49	
 50	import java.sql.Connection;
 51	import java.sql.DriverManager;
 52	import java.sql.Statement;
 53	
 54	public class Database {
 55	    private static String dbUrl;
 56	    private static String dbUser;
 57	    private static String dbPassword;
 58	
 59	    public static void init() {
 60	        dbUrl = System.getenv("DB_URL");
 61	        dbUser = System.getenv("DB_USER");
 62	        dbPassword = System.getenv("DB_PASSWORD");
 63	
 64	        if (dbUrl == null) {
 65	            throw new RuntimeException("DB_URL environment variable not set");
 66	        }
 67	
 68	        try {
 69	            createTables();
 70	            seedRooms();
 71	        } catch (Exception e) {
 72	            throw new RuntimeException("Failed to initialize database", e);
 73	        }
 74	    }
 75	
 76	    private static void createTables() throws Exception {
 77	        try (Connection conn = getConnection();
 78	             Statement stmt = conn.createStatement()) {
 79	
 80	            stmt.execute("""
 81	                CREATE TABLE IF NOT EXISTS rooms (
 82	                    number INT PRIMARY KEY,
 83	                    type VARCHAR(50) NOT NULL,
 84	                    capacity INT NOT NULL,
 85	                    nightly_rate NUMERIC(10, 2) NOT NULL
 86	                )
 87	                """);
 88	
 89	            stmt.execute("""
 90	                CREATE TABLE IF NOT EXISTS reservations (
 91	                    id SERIAL PRIMARY KEY,
 92	                    room_number INT NOT NULL,
 93	                    guest_name VARCHAR(255) NOT NULL,
 94	                    guest_email VARCHAR(255) NOT NULL,
 95	                    guest_cpf VARCHAR(20) NOT NULL,
 96	                    check_in DATE NOT NULL,
 97	                    check_out DATE NOT NULL,
 98	                    guests INT NOT NULL,
 99	                    rate_plan VARCHAR(50) NOT NULL,
100	                    nights INT NOT NULL,
101	                    subtotal NUMERIC(10, 2) NOT NULL,
102	                    discount NUMERIC(10, 2) NOT NULL,
103	                    total NUMERIC(10, 2) NOT NULL,
104	                    status VARCHAR(50) NOT NULL,
105	                    amount_paid NUMERIC(10, 2) NOT NULL DEFAULT 0,
106	                    refund NUMERIC(10, 2),
107	                    FOREIGN KEY (room_number) REFERENCES rooms(number)
108	                )
109	                """);
110	
111	            stmt.execute("""
112	                CREATE TABLE IF NOT EXISTS messages (
113	                    id SERIAL PRIMARY KEY,
114	                    channel VARCHAR(50) NOT NULL,
115	                    to_address VARCHAR(255) NOT NULL,
116	                    subject VARCHAR(500) NOT NULL,
117	                    body TEXT NOT NULL
118	                )
119	                """);
120	
121	            conn.commit();
122	        }
123	    }
124	
125	    private static void seedRooms() throws Exception {
126	        try (Connection conn = getConnection();
127	             Statement stmt = conn.createStatement()) {
128	
129	            var countResult = stmt.executeQuery("SELECT COUNT(*) FROM rooms");
130	            countResult.next();
131	            if (countResult.getInt(1) == 0) {
132	                stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (101, 'STANDARD', 2, 249.90)");
133	                stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (102, 'STANDARD', 2, 249.90)");
134	                stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (201, 'DELUXE', 3, 389.90)");
135	                stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (202, 'DELUXE', 3, 389.90)");
136	                stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (301, 'SUITE', 4, 579.90)");
137	            }
138	            conn.commit();
139	        }
140	    }
141	
142	    public static Connection getConnection() throws Exception {
143	        return DriverManager.getConnection(dbUrl, dbUser, dbPassword);
144	    }
145	}
