294	    public void createReservation(Context ctx) {
295	        try {
296	            var body = ctx.bodyAsClass(Map.class);
297	
298	            // Validate required fields
299	            String[] required = {"roomNumber", "guestName", "guestEmail", "guestCpf", "checkIn", "checkOut", "guests", "ratePlan"};
300	            for (String field : required) {
301	                if (!body.containsKey(field)) {
302	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing required field: " + field));
303	                    return;
304	                }
305	            }
306	
307	            int roomNumber = ((Number) body.get("roomNumber")).intValue();
308	            String guestName = (String) body.get("guestName");
309	            String guestEmail = (String) body.get("guestEmail");
310	            String guestCpf = (String) body.get("guestCpf");
311	            LocalDate checkIn = DateFormatter.parse((String) body.get("checkIn"));
312	            LocalDate checkOut = DateFormatter.parse((String) body.get("checkOut"));
313	            int guests = ((Number) body.get("guests")).intValue();
314	            String ratePlan = (String) body.get("ratePlan");
315	
316	            Reservation reservation = reservationService.createReservation(
317	                roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests, ratePlan);
318	
319	            ctx.status(201).json(reservationToJson(reservation));
320	        } catch (ReservationService.ValidationException e) {
321	            if ("ROOM_NOT_FOUND".equals(e.errorCode)) {
322	                ctx.status(404).json(new ErrorResponse(e.errorCode, e.getMessage()));
323	            } else if ("ROOM_UNAVAILABLE".equals(e.errorCode)) {
324	                ctx.status(409).json(new ErrorResponse(e.errorCode, e.getMessage()));
325	            } else if ("CAPACITY_EXCEEDED".equals(e.errorCode)) {
326	                ctx.status(422).json(new ErrorResponse(e.errorCode, e.getMessage()));
327	            } else {
328	                ctx.status(400).json(new ErrorResponse(e.errorCode, e.getMessage()));
329	            }
330	        } catch (Exception e) {
331	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
332	        }
333	    }
