458	    private Map<String, Object> reservationToJson(Reservation res) {
459	        Map<String, Object> map = new HashMap<>();
460	        map.put("id", res.id);
461	        map.put("roomNumber", res.roomNumber);
462	        map.put("guestName", res.guestName);
463	        map.put("guestEmail", res.guestEmail);
464	        map.put("guestCpf", res.guestCpf);
465	        map.put("checkIn", DateFormatter.formatISO(res.checkIn));
466	        map.put("checkOut", DateFormatter.formatISO(res.checkOut));
467	        map.put("guests", res.guests);
468	        map.put("ratePlan", res.ratePlan);
469	        map.put("nights", res.nights);
470	        map.put("subtotal", res.subtotal.doubleValue());
471	        map.put("discount", res.discount.doubleValue());
472	        map.put("total", res.total.doubleValue());
473	        map.put("status", res.status);
474	        map.put("amountPaid", res.amountPaid.doubleValue());
475	        map.put("refund", res.refund != null ? res.refund.doubleValue() : null);
476	        return map;
477	    }
