 28	package com.pousadamarealta.service;
 29	
 30	import java.math.BigDecimal;
 31	import java.math.RoundingMode;
 32	import java.time.LocalDate;
 33	
 34	public class PricingService {
 35	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
 36	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
 37	
 38	    public static boolean isHighSeason(LocalDate date) {
 39	        int month = date.getMonthValue();
 40	        int day = date.getDayOfMonth();
 41	
 42	        if ((month == 12 && day >= 15) || (month == 1 || month == 2)) {
 43	            return true;
 44	        }
 45	        if (month == 7) {
 46	            return true;
 47	        }
 48	        return false;
 49	    }
 50	
 51	    public static BigDecimal calculateNightlyRate(BigDecimal baseRate, LocalDate date) {
 52	        if (isHighSeason(date)) {
 53	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER)
 54	                .setScale(2, RoundingMode.HALF_EVEN);
 55	        }
 56	        return baseRate.setScale(2, RoundingMode.HALF_EVEN);
 57	    }
 58	
 59	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
 60	        BigDecimal subtotal = BigDecimal.ZERO;
 61	        LocalDate current = checkIn;
 62	        while (current.isBefore(checkOut)) {
 63	            subtotal = subtotal.add(calculateNightlyRate(baseRate, current));
 64	            current = current.plusDays(1);
 65	        }
 66	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
 67	    }
 68	
 69	    public static BigDecimal calculateDiscount(BigDecimal subtotal, String ratePlan) {
 70	        if ("NON_REFUNDABLE".equals(ratePlan)) {
 71	            return subtotal.multiply(NON_REFUNDABLE_DISCOUNT)
 72	                .setScale(2, RoundingMode.HALF_EVEN);
 73	        }
 74	        return BigDecimal.ZERO.setScale(2, RoundingMode.HALF_EVEN);
 75	    }
 76	
 77	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
 78	        return subtotal.subtract(discount)
 79	            .setScale(2, RoundingMode.HALF_EVEN);
 80	    }
 81	
 82	    public static int calculateNights(LocalDate checkIn, LocalDate checkOut) {
 83	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
 84	    }
 85	}
