102	public class ReportService {
103	    private final ReservationRepository reservationRepository = new ReservationRepository();
104	    private final RoomRepository roomRepository = new RoomRepository();
105	
106	    public String generateOccupancyReport(LocalDate date) throws Exception {
107	        List<Reservation> reservations = reservationRepository.findByDate(date);
108	        List<Room> allRooms = roomRepository.findAll();
109	
110	        StringBuilder csv = new StringBuilder();
111	        csv.append("Pousada Maré Alta,occupancy,").append(DateFormatter.formatISO(date)).append("\n");
112	        csv.append("room,type,reservation,check_in,check_out\n");
113	
114	        int occupiedCount = 0;
115	        for (Room room : allRooms) {
116	            boolean found = false;
117	            for (Reservation res : reservations) {
118	                if (res.roomNumber == room.number) {
119	                    csv.append(room.number).append(",")
120	                        .append(room.type).append(",")
121	                        .append(res.id).append(",")
122	                        .append(DateFormatter.formatISO(res.checkIn)).append(",")
123	                        .append(DateFormatter.formatISO(res.checkOut)).append("\n");
124	                    occupiedCount++;
125	                    found = true;
126	                    break;
127	                }
128	            }
129	        }
130	
131	        csv.append("total,").append(occupiedCount).append("/").append(allRooms.size()).append("\n");
132	        return csv.toString();
133	    }
134	
135	    public String generateRevenueReport(YearMonth month) throws Exception {
136	        LocalDate monthStart = month.atDay(1);
137	        LocalDate monthEnd = month.atEndOfMonth().plusDays(1);
138	
139	        List<Reservation> reservations = reservationRepository.findByMonth(monthStart, monthEnd);
140	
141	        StringBuilder csv = new StringBuilder();
142	        csv.append("Pousada Maré Alta,revenue,").append(month).append("\n");
143	        csv.append("reservation,room,check_in,check_out,status,amount\n");
144	
145	        BigDecimal total = BigDecimal.ZERO;
146	
147	        for (Reservation res : reservations) {
148	            if ("CANCELLED".equals(res.status)) {
149	                // Only count cancelled if they have refund info (i.e., were confirmed)
150	                if (res.amountPaid.compareTo(BigDecimal.ZERO) == 0) continue;
151	            }
152	
153	            if (!"PENDING".equals(res.status)) {
154	                BigDecimal amount = res.amountPaid;
155	                if (res.refund != null) {
156	                    amount = amount.subtract(res.refund);
157	                }
158	
159	                csv.append(res.id).append(",")
