281	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
282	                                        LocalDate checkIn, LocalDate checkOut, int guests, String ratePlan) throws Exception {
283	        // Validate room exists
284	        Room room = roomRepository.findByNumber(roomNumber)
285	            .orElseThrow(() -> new ValidationException("ROOM_NOT_FOUND", "Room not found"));
286	
287	        // Validate guests
288	        if (guests < 1 || guests > room.capacity) {
