290	        }
291	
292	        // Validate dates
293	        if (!checkOut.isAfter(checkIn)) {
294	            throw new ValidationException("INVALID_REQUEST", "Check-out must be after check-in");
295	        }
296	
297	        // Check room availability
298	        if (reservationRepository.hasConflict(roomNumber, checkIn, checkOut)) {
299	            throw new ValidationException("ROOM_UNAVAILABLE", "Room is not available for these dates");
300	        }
301	
302	        // Calculate pricing
303	        int nights = PricingService.calculateNights(checkIn, checkOut);
304	        BigDecimal subtotal = PricingService.calculateSubtotal(room.nightlyRate, checkIn, checkOut);
305	        BigDecimal discount = PricingService.calculateDiscount(subtotal, ratePlan);
306	        BigDecimal total = PricingService.calculateTotal(subtotal, discount);
307	
308	        // Create reservation
309	        return reservationRepository.create(roomNumber, guestName, guestEmail, guestCpf,
310	            checkIn, checkOut, guests, ratePlan, nights, subtotal, discount, total);
311	    }
