321	        if (!"PENDING".equals(res.status)) {
322	            throw new ValidationException("OPERATION_NOT_ALLOWED", "Only pending reservations can be confirmed");
323	        }
324	
325	        reservationRepository.updateStatus(id, "CONFIRMED");
326	        reservationRepository.updateAmountPaid(id, res.total);
327	
328	        Reservation updated = getReservation(id);
329	
