389	        Reservation res = getReservation(id);
390	
391	        if ("PENDING".equals(res.status) || "CANCELLED".equals(res.status)) {
392	            throw new ValidationException("OPERATION_NOT_ALLOWED", "Document only available for confirmed or checked-in reservations");
393	        }
