332	        Document doc = new Document(res.id, res.guestName, res.guestCpf, res.roomNumber, room.type,
333	            res.checkIn, res.checkOut, res.nights, res.subtotal, res.discount, res.total);
334	
335	        // Send confirmation email
336	        messageService.sendConfirmationEmail(res, doc);
337	
338	        return updated;
339	    }
340	
341	    public Reservation cancelReservation(int id) throws Exception {
342	        Reservation res = getReservation(id);
343	
344	        if ("CHECKED_IN".equals(res.status) || "CHECKED_OUT".equals(res.status) || "CANCELLED".equals(res.status)) {
345	            throw new ValidationException("OPERATION_NOT_ALLOWED", "Cannot cancel reservation in current status");
346	        }
347	
348	        reservationRepository.updateStatus(id, "CANCELLED");
349	
350	        // Calculate refund
351	        BigDecimal refund = BigDecimal.ZERO;
352	        if ("CONFIRMED".equals(res.status)) {
353	            if ("STANDARD".equals(res.ratePlan)) {
354	                refund = res.amountPaid;
355	            }
356	        }
357	        // PENDING has no refund as nothing was paid
358	
359	        if (refund.compareTo(BigDecimal.ZERO) > 0) {
360	            reservationRepository.updateRefund(id, refund);
361	        }
362	
363	        return getReservation(id);
364	    }
365	
366	    public Reservation checkInReservation(int id) throws Exception {
367	        Reservation res = getReservation(id);
368	
369	        if (!"CONFIRMED".equals(res.status)) {
370	            throw new ValidationException("OPERATION_NOT_ALLOWED", "Only confirmed reservations can check in");
371	        }
372	
373	        reservationRepository.updateStatus(id, "CHECKED_IN");
374	        return getReservation(id);
375	    }
376	
377	    public Reservation checkOutReservation(int id) throws Exception {
378	        Reservation res = getReservation(id);
379	
380	        if (!"CHECKED_IN".equals(res.status)) {
381	            throw new ValidationException("OPERATION_NOT_ALLOWED", "Only checked-in reservations can check out");
382	        }
383	
384	        reservationRepository.updateStatus(id, "CHECKED_OUT");
385	        return getReservation(id);
386	    }
387	
388	    public Document getDocument(int id) throws Exception {
389	        Reservation res = getReservation(id);
390	
391	        if ("PENDING".equals(res.status) || "CANCELLED".equals(res.status)) {
392	            throw new ValidationException("OPERATION_NOT_ALLOWED", "Document only available for confirmed or checked-in reservations");
393	        }
394	
395	        Room room = roomRepository.findByNumber(res.roomNumber).orElseThrow();
396	        return new Document(res.id, res.guestName, res.guestCpf, res.roomNumber, room.type,
397	            res.checkIn, res.checkOut, res.nights, res.subtotal, res.discount, res.total);
398	    }
399	
400	    public static class ValidationException extends Exception {
401	        public String errorCode;
402	
403	        public ValidationException(String errorCode, String message) {
404	            super(message);
405	            this.errorCode = errorCode;
406	        }
407	    }
408	}

