298	public class DocumentFormatter {
299	    public static String formatAsText(Document doc) {
300	        StringBuilder sb = new StringBuilder();
301	        sb.append("Comprovante de reserva nº ").append(doc.reservationId).append("\n");
302	        sb.append(String.format("Hóspede: %s (CPF %s)\n", doc.guestName, formatCpf(doc.guestCpf)));
303	        sb.append(String.format("Quarto: %d (%s)\n", doc.roomNumber, doc.roomType));
304	        sb.append(String.format("Entrada: %s | Saída: %s | %d %s\n",
305	            DateFormatter.format(doc.checkIn),
306	            DateFormatter.format(doc.checkOut),
307	            doc.nights,
308	            doc.nights == 1 ? "diária" : "diárias"));
309	        sb.append(String.format("Diárias: %s\n", CurrencyFormatter.format(doc.subtotal)));
310	
311	        if (doc.discount.compareTo(BigDecimal.ZERO) > 0) {
312	            sb.append(String.format("Desconto: %s\n", CurrencyFormatter.format(doc.discount)));
313	        }
314	
315	        sb.append(String.format("Total: %s", CurrencyFormatter.format(doc.total)));
316	        return sb.toString();
317	    }
318	
319	    private static String formatCpf(String cpf) {
320	        if (cpf == null || cpf.length() != 11) return cpf;
321	        return String.format("%s.%s.%s-%s",
322	            cpf.substring(0, 3),
323	            cpf.substring(3, 6),
324	            cpf.substring(6, 9),
325	            cpf.substring(9, 11));
326	    }
327	}
